update iot_control_event
control_id = #{controlId}, alert_record_id = #{alertRecordId}, device_id = #{deviceId}, device_sn = #{deviceSn}, target_model_id = #{targetModelId}, target_identifier = #{targetIdentifier}, topic = #{topic}, payload = #{payload}, response_payload = #{responsePayload}, response_desc = #{responseDesc}, status = #{status}, send_time = #{sendTime}, response_time = #{responseTime}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where event_id = #{eventId}

update iot_control_event
set status = 2,
    response_payload = #{responsePayload},
    response_desc = #{responseDesc},
    response_time = sysdate(),
    update_time = sysdate()
where device_sn = #{deviceSn}
  and status = 1
  and json_valid(payload)
  and json_unquote(json_extract(payload, '$.res')) = #{res}
  and send_time = (
      select max_send_time
      from (
          select max(send_time) as max_send_time
          from iot_control_event
          where device_sn = #{deviceSn}
            and status = 1
            and json_valid(payload)
            and json_unquote(json_extract(payload, '$.res')) = #{res}
      ) t
  )
